        alignment: AlignmentType.CENTER,
        spacing: { before: 480, after: 160 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "AI Integration into Human Biological Substrate", size: 28, font: "Arial", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Corrected and Expanded with Verified Citations", size: 24, font: "Arial", italics: true, color: "555555" })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 80 }
      }),
